 7	/**
 8	 * Creates a minimal `AppConfig` suitable for use in unit tests.
 9	 *
10	 * `storageFolder` and `projectsFolder` are derived from the supplied `base`
11	 * directory so that each test can work inside its own isolated temp tree.
12	 * All other fields are set to sensible defaults that match production
13	 * defaults.  Pass `overrides` to adjust individual fields without having to
14	 * repeat the full object literal.
15	 *
16	 * @param base      - Root temp-directory for this test (e.g. the value
17	 *                    returned by your `makeTempDir()` call).
18	 * @param overrides - Optional partial config to merge on top of the defaults.
19	 * @returns A complete `AppConfig` object.
20	 */
21	export function makeTestConfig(base: string, overrides?: Partial<AppConfig>): AppConfig {
22	    return {
23	        storageFolder: path.join(base, 'storage'),
24	        projectsFolder: path.join(base, 'projects'),
25	        cloneDepth: 50,
26	        serverPort: 4200,
27	        gitPollingIntervalSeconds: 30,
28	        notesCardHeight: 220,
29	        notesColumns: 2,
30	        ...overrides,
31	    };
32	}
33	
34	/**
35	 * Creates a temp-directory tracker that auto-cleans all created directories
36	 * on process exit. Call the returned function to create a new temp directory.
37	 *
38	 * @param prefix - The temp directory name prefix (e.g. `'paralizer-config-test-'`).
39	 * @returns A `makeTempDir()` function that creates and tracks temp directories.
40	 */
41	export function createTempDirTracker(prefix: string): () => string {
42	    const cleanupPaths: string[] = [];
43	    process.on('exit', () => {
44	        for (const p of cleanupPaths) {
45	            fs.rmSync(p, { recursive: true, force: true });
46	        }
47	    });
48	    return (): string => {
49	        const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
50	        cleanupPaths.push(dir);
51	        return dir;
52	    };
53	}
54	
55	/**
56	 * Creates a fake `git` executable in `dir` that records all invocation
57	 * arguments to `dir/captured-args.txt` and exits with code 128 (simulating a
58	 * failed clone).  The real git binary is never called.
59	 *
60	 * @returns Path of the file where captured arguments are written.
61	 */
62	export function setupFakeGit(dir: string): string {
63	    const capturedArgsFile = path.join(dir, 'captured-args.txt');
64	    const fakeGitPath = path.join(dir, 'git');
65	    fs.writeFileSync(
66	        fakeGitPath,
67	        `#!/bin/sh\necho "$@" >> ${capturedArgsFile}\nexit 128\n`,
68	        { mode: 0o755 },
69	    );
70	    return capturedArgsFile;
71	}

